import { KEYS, getJson, putJson, headObject, listObjects } from "./store.mjs";
import { encodeSegment } from "./ids.mjs";
import { invalidRequestBody } from "./problems.mjs";

// Metadata objects: the Space's, each Collection's (its configuration plus
// the user-writable `custom`/`epoch` annotation) and each Resource's. Each
// is one JSON object under meta/, versioned by its own S3 ETag, which comes
// back on reads and writes and is honored as If-Match / If-None-Match.

// Members the server owns on a metadata object; a client-supplied value is
// dropped before storing (the same list @interop/was-client never echoes).
const SERVER_MANAGED = new Set([
  "id",
  "type",
  "etag",
  "url",
  "linkset",
  "createdAt",
  "updatedAt",
  "createdBy",
  "created",
  "updatedAtCounter",
  "originId",
]);

export const now = () => new Date().toISOString();

export function stripServerManaged(body) {
  return Object.fromEntries(Object.entries(body).filter(([member]) => !SERVER_MANAGED.has(member)));
}

export const spaceUrl = (req, spaceId) => `${req.base}/space/${encodeSegment(spaceId)}/`;
export const collectionUrl = (req, spaceId, collectionId) =>
  `${spaceUrl(req, spaceId)}${encodeSegment(collectionId)}/`;
export const resourceUrl = (req, spaceId, collectionId, resourceId) =>
  `${collectionUrl(req, spaceId, collectionId)}${encodeSegment(resourceId)}`;

const isObject = (value) => typeof value === "object" && value !== null && !Array.isArray(value);

// The type array of a metadata object: stamped when absent, and required to
// name the container kind when given.
export function typesOf(body, kind) {
  if (body.type === undefined) {
    return [kind];
  }
  const types = Array.isArray(body.type) ? body.type : [body.type];
  if (!types.every((entry) => typeof entry === "string") || !types.includes(kind)) {
    throw invalidRequestBody(`"type" must be an array of strings that includes "${kind}".`);
  }
  return types;
}

// Validates the writable members a client may put on Collection Metadata.
export function validateCollectionFields(fields) {
  if (fields.name !== undefined && typeof fields.name !== "string") {
    throw invalidRequestBody('"name" must be a string.');
  }
  if (fields.encryption !== undefined && fields.encryption !== null) {
    if (!isObject(fields.encryption) || typeof fields.encryption.scheme !== "string") {
      throw invalidRequestBody('"encryption" must be an object with a string "scheme".');
    }
  }
  if (fields.custom !== undefined && fields.custom !== null && !isObject(fields.custom)) {
    throw invalidRequestBody('"custom" must be an object.');
  }
  if (fields.epoch !== undefined && typeof fields.epoch !== "string") {
    throw invalidRequestBody('"epoch" must be a string.');
  }
  if (fields.backend !== undefined && !isObject(fields.backend) && typeof fields.backend !== "string") {
    throw invalidRequestBody('"backend" must be an object or a string.');
  }
}

// --- Space -----------------------------------------------------------------

export async function readSpaceMeta(req, spaceId) {
  const stored = await getJson(spaceId, KEYS.spaceMeta());
  if (stored === null) {
    return null;
  }
  return {
    doc: { ...stored.doc, id: spaceId, url: spaceUrl(req, spaceId) },
    etag: stored.etag,
  };
}

export async function writeSpaceMeta(req, spaceId, doc, preconditions) {
  const { etag } = await putJson(spaceId, KEYS.spaceMeta(), doc, preconditions);
  return { doc: { ...doc, url: spaceUrl(req, spaceId) }, etag };
}

// --- Collection ------------------------------------------------------------

// Whether any object exists under the collection's content prefix.
export async function hasContent(bucket, collectionId) {
  const page = await listObjects(bucket, { prefix: KEYS.collectionPrefix(collectionId), limit: 1 });
  return page.objects.length > 0;
}

// The stored Collection Metadata, or a synthesized plaintext one for an
// implicit collection (content exists under the prefix but no metadata was
// ever written, e.g. written directly to the bucket by an issuer service);
// null when neither exists. A synthesized document has no ETag.
export async function readCollectionMeta(req, spaceId, collectionId) {
  const stored = await getJson(spaceId, KEYS.collectionMeta(collectionId));
  if (stored !== null) {
    return {
      doc: { ...stored.doc, id: collectionId, url: collectionUrl(req, spaceId, collectionId) },
      etag: stored.etag,
    };
  }
  if (await hasContent(spaceId, collectionId)) {
    return {
      doc: { id: collectionId, type: ["Collection"], url: collectionUrl(req, spaceId, collectionId) },
      etag: undefined,
    };
  }
  return null;
}

export function composeCollectionMeta({ collectionId, body, stored, invoker }) {
  const fields = stripServerManaged(body);
  validateCollectionFields(fields);
  const type = typesOf(body, "Collection");
  const stamp = now();
  // A null member (e.g. "encryption": null) means cleared.
  for (const member of Object.keys(fields)) {
    if (fields[member] === null) {
      delete fields[member];
    }
  }
  return {
    ...fields,
    id: collectionId,
    type,
    createdAt: stored?.createdAt ?? stamp,
    updatedAt: stamp,
    ...((stored?.createdBy ?? invoker) && { createdBy: stored?.createdBy ?? invoker }),
  };
}

export async function writeCollectionMeta(req, spaceId, collectionId, doc, preconditions) {
  const { etag } = await putJson(spaceId, KEYS.collectionMeta(collectionId), doc, preconditions);
  return { doc: { ...doc, url: collectionUrl(req, spaceId, collectionId) }, etag };
}

// Gives a collection that has content but no metadata (a first resource
// write into a new collection) a plaintext metadata object, so the
// collection is listed and its /meta is versioned. Losing the race to a
// concurrent writer is fine: the other document stands.
export async function ensureCollectionMeta(spaceId, collectionId, invoker) {
  if ((await headObject(spaceId, KEYS.collectionMeta(collectionId))) !== null) {
    return;
  }
  const doc = composeCollectionMeta({ collectionId, body: {}, stored: null, invoker });
  try {
    await putJson(spaceId, KEYS.collectionMeta(collectionId), doc, { ifNoneMatch: "*" });
  } catch (err) {
    if (err?.status !== 412) {
      throw err;
    }
  }
}

// --- Resource --------------------------------------------------------------

// Object metadata keys stamped on a Resource's content object (S3 lowercases
// them). The content write is the authority for these; the /meta document
// only carries the user-writable annotation.
export const CONTENT_META = {
  createdAt: "created-at",
  createdBy: "created-by",
  epoch: "key-epoch",
  writerId: "writer-id",
};

// The Resource Metadata object: derived members from the content object's
// head, merged with the stored annotation document. `etag` is the stored
// document's, absent until a /meta write has happened.
export function resourceMetaDoc({ head, stored }) {
  const meta = head.metadata ?? {};
  return {
    contentType: head.contentType ?? "application/octet-stream",
    size: head.contentLength ?? 0,
    ...(meta[CONTENT_META.createdAt] && { createdAt: meta[CONTENT_META.createdAt] }),
    updatedAt: stored?.doc?.updatedAt ?? head.lastModified?.toISOString?.() ?? now(),
    ...(meta[CONTENT_META.createdBy] && { createdBy: meta[CONTENT_META.createdBy] }),
    ...(meta[CONTENT_META.epoch] && { epoch: meta[CONTENT_META.epoch] }),
    ...(meta[CONTENT_META.writerId] && { writerId: meta[CONTENT_META.writerId] }),
    ...(stored?.doc?.custom !== undefined && { custom: stored.doc.custom }),
  };
}

export async function readResourceMeta(spaceId, collectionId, resourceId) {
  const head = await headObject(spaceId, KEYS.resource(collectionId, resourceId));
  if (head === null) {
    return null;
  }
  const stored = await getJson(spaceId, KEYS.resourceMeta(collectionId, resourceId));
  return { doc: resourceMetaDoc({ head, stored }), etag: stored?.etag, head, stored };
}
